//! Campaign module expressibility.
//!
//! The permutations generated by a transposition and a 3-cycle are all of
//! `S3`. The BFS closure has size 6, and that size is also `3!`.

pub fn verify() -> Result<usize, &'static str> {
    let transposition = [1usize, 0, 2];
    let cycle = [1usize, 2, 0];
    let mut group = vec![[0usize, 1, 2]];
    let mut cursor = 0usize;
    while cursor < group.len() {
        let current = group[cursor];
        cursor += 1;
        for generator in [transposition, cycle] {
            let next = compose(generator, current);
            if !group.contains(&next) {
                group.push(next);
            }
        }
    }
    let factorial = 6usize;
    if group.len() != factorial {
        return Err("generated group is not S3");
    }
    Ok(group.len())
}

fn compose(left: [usize; 3], right: [usize; 3]) -> [usize; 3] {
    [left[right[0]], left[right[1]], left[right[2]]]
}
